-- GENERATED by homeassistant/bundle.py from src/ha.lua, src/draw.lua and src/lock/lock.lua
-- -- edit those files, not this one.
local H = (function()
-- Home Assistant pieces shared by the app (src/main.lua) and the lock screen (lockscreen.lua,
-- which carries its own copy: lock entries load alone): settings and the tile list, the REST
-- requests, the states cache and how a state is shown.
--
-- ha.txt (settings; can be written over USB): url, token, title, lock (true|false), each "key=value".
-- tiles.txt: one entity a line, "entity_id" or "entity_id = Label"; a leading "*" puts it on the
--   lock screen; "#" starts a comment. Edited in the app or over USB.
-- states.txt (the cache, written by whoever fetched last): "updated=<epoch>", then
--   "entity|state|unit|name|class|extra" lines.
--
-- All tiles come in one request: POST /api/template renders a few lines of text for exactly the
-- entities on the panel (each HTTPS request costs ~1.4 s on the device and the heap is ~1 MB, so
-- /api/states, every entity of the house as JSON, is out). The template API needs an admin's
-- token; for any other token the app falls back to GET /api/states/<entity> one by one.

local H = {}

function H.kv(s)
  local t = {}
  for k, v in (s or ''):gmatch('([%w_]+)=([^\n]*)') do t[k] = (v:gsub('%s+$', '')) end
  return t
end

------------------------------------------------------------------ settings and tiles

-- "192.168.1.5:8123/" -> "http://192.168.1.5:8123"
function H.base(url)
  url = tostring(url or ''):gsub('^%s+', ''):gsub('%s+$', ''):gsub('/+$', '')
  if url ~= '' and not url:match('^https?://') then url = 'http://' .. url end
  return url
end

function H.parse_cfg(s)
  local t = H.kv(s)
  return { url = H.base(t.url), token = t.token or '', title = (t.title and t.title ~= '') and t.title or 'Home',
           lock = t.lock == 'true' }
end
function H.cfg_text(c)
  return 'url=' .. (c.url or '') .. '\ntoken=' .. (c.token or '') .. '\ntitle=' .. (c.title or 'Home') ..
    '\nlock=' .. tostring(c.lock == true)
end

function H.valid_id(id) return type(id) == 'string' and id:match('^[%l%d_]+%.[%l%d_]+$') ~= nil end
function H.domain(id) return (tostring(id):match('^([^.]+)%.')) or '' end

function H.parse_tiles(s)
  local out = {}
  for raw in ((s or '') .. '\n'):gmatch('([^\n]*)\n') do
    local line = raw:gsub('\r', ''):gsub('#.*$', ''):gsub('^%s+', ''):gsub('%s+$', '')
    local pin = line:sub(1, 1) == '*'
    if pin then line = line:sub(2):gsub('^%s+', '') end
    local id, label = line:match('^([^=]-)%s*=%s*(.-)$')
    id = (id or line):lower()
    if H.valid_id(id) then out[#out + 1] = { id = id, label = (label and label ~= '') and label or nil, pin = pin } end
  end
  return out
end
function H.tiles_text(list)
  local out = { '# one entity a line: "entity_id" or "entity_id = Label"; "*" in front puts it on the lock screen' }
  for _k, t in ipairs(list) do out[#out + 1] = (t.pin and '*' or '') .. t.id .. (t.label and (' = ' .. t.label) or '') end
  return table.concat(out, '\n') .. '\n'
end

-- the tiles of the lock screen: the pinned ones, or the first eight when none is pinned
function H.lock_tiles(list)
  local out = {}
  for _k, t in ipairs(list) do if t.pin then out[#out + 1] = t end end
  if #out == 0 then for k = 1, math.min(8, #list) do out[k] = list[k] end end
  while #out > 8 do table.remove(out) end
  return out
end

------------------------------------------------------------------ requests

-- a JSON string (the device's ctx.json:encode is not probed; this is all a request body needs)
function H.json_str(s)
  return '"' .. tostring(s):gsub('[%c"\\]', function(c)
    if c == '"' then return '\\"' elseif c == '\\' then return '\\\\' elseif c == '\n' then return '\\n'
    elseif c == '\t' then return '\\t' end
    return string.format('\\u%04x', c:byte())
  end) .. '"'
end

local function headers(token)
  return { ['Authorization'] = 'Bearer ' .. tostring(token or ''), ['Content-Type'] = 'application/json',
           ['Accept'] = 'application/json, text/plain' }
end

-- one line per entity: id|state|unit|name|device class|extra (by domain: a thermostat's
-- "current;target;action", the target "21" or a range "18~24"; a light's brightness %; a cover's
-- position; the media title)
local ROW = "{{ e }}|{{ states(e)|replace('|','/')|replace('\\n',' ') }}|{{ state_attr(e,'unit_of_measurement') or '' }}|" ..
  "{{ (state_attr(e,'friendly_name') or e)|replace('|','/')|replace('\\n',' ') }}|{{ state_attr(e,'device_class') or '' }}|" ..
  "{% set d = e.split('.')[0] %}{% if d == 'climate' %}{{ state_attr(e,'current_temperature') if state_attr(e,'current_temperature') is not none else '' }};" ..
  "{% if state_attr(e,'temperature') is not none %}{{ state_attr(e,'temperature') }}" ..
  "{% elif state_attr(e,'target_temp_low') is not none %}{{ state_attr(e,'target_temp_low') }}~{{ state_attr(e,'target_temp_high') }}{% endif %};" ..
  "{{ state_attr(e,'hvac_action') or '' }}" ..
  "{% elif d == 'light' and state_attr(e,'brightness') %}{{ (state_attr(e,'brightness') / 2.55)|round|int }}" ..
  "{% elif d == 'cover' and state_attr(e,'current_position') is not none %}{{ state_attr(e,'current_position') }}" ..
  "{% elif d == 'media_player' %}{{ (state_attr(e,'media_title') or '')|replace('|','/')|replace('\\n',' ') }}{% endif %}\n"

function H.template(ids)
  local q = {}
  for _k, id in ipairs(ids) do if H.valid_id(id) then q[#q + 1] = "'" .. id .. "'" end end
  return '{% for e in [' .. table.concat(q, ',') .. '] %}' .. ROW .. '{% endfor %}'
end

function H.states_request(cfg, ids)
  return { url = cfg.url .. '/api/template', method = 'POST', headers = headers(cfg.token),
           body = '{"template":' .. H.json_str(H.template(ids)) .. '}', timeout_ms = 30000 }
end

function H.state_request(cfg, id)
  return { url = cfg.url .. '/api/states/' .. id, method = 'GET', headers = headers(cfg.token), timeout_ms = 20000 }
end

function H.ping_request(cfg)
  return { url = cfg.url .. '/api/', method = 'GET', headers = headers(cfg.token), timeout_ms = 20000 }
end

-- entities whose id or name holds q, at most 40
function H.search_request(cfg, q)
  q = tostring(q or ''):lower():gsub("[\\'{}%%]", ''):gsub('^%s+', ''):gsub('%s+$', '')
  local t = "{% set q = '" .. q .. "' %}{% set ns = namespace(n=0) %}{% for s in states|sort(attribute='entity_id') %}" ..
    "{% if ns.n < 40 and (q in s.entity_id or q in (s.name|lower)) %}{% set ns.n = ns.n + 1 %}" ..
    "{{ s.entity_id }}|{{ s.state|replace('|','/')|replace('\\n',' ') }}|{{ s.attributes.unit_of_measurement or '' }}|" ..
    "{{ s.name|replace('|','/')|replace('\\n',' ') }}|{{ s.attributes.device_class or '' }}|\n{% endif %}{% endfor %}"
  return { url = cfg.url .. '/api/template', method = 'POST', headers = headers(cfg.token),
           body = '{"template":' .. H.json_str(t) .. '}', timeout_ms = 30000 }
end

-- a small JSON encoder for service data: strings, numbers, booleans, arrays and string-keyed tables
-- (keys sorted, so the body is the same every time)
function H.json(v)
  local t = type(v)
  if t == 'string' then return H.json_str(v) end
  if t == 'boolean' then return tostring(v) end
  if t == 'number' then
    if v == math.floor(v) and math.abs(v) < 2 ^ 31 then return string.format('%d', math.floor(v)) end
    return (string.format('%.3f', v):gsub('0+$', ''):gsub('%.$', ''))
  end
  if t == 'table' then
    if #v > 0 then
      local o = {}
      for i, x in ipairs(v) do o[i] = H.json(x) end
      return '[' .. table.concat(o, ',') .. ']'
    end
    local keys = {}
    for k in pairs(v) do keys[#keys + 1] = tostring(k) end
    table.sort(keys)
    local o = {}
    for _k, k in ipairs(keys) do o[#o + 1] = H.json_str(k) .. ':' .. H.json(v[k]) end
    return '{' .. table.concat(o, ',') .. '}'
  end
  return 'null'
end

-- data: further service fields, as { brightness_pct = 40 }
function H.service_request(cfg, id, domain, service, data)
  local body = { entity_id = id }
  for k, v in pairs(data or {}) do body[k] = v end
  return { url = cfg.url .. '/api/services/' .. domain .. '/' .. service, method = 'POST', headers = headers(cfg.token),
           body = H.json(body), timeout_ms = 20000 }
end

------------------------------------------------------------------ what an entity can do

-- the value of a JSON attribute only when it is a number / a string (JSON null decodes to a sentinel)
function H.num(v) return type(v) == 'number' and v or nil end
function H.str(v) return type(v) == 'string' and v or nil end
function H.has(features, bit) return ((math.floor(H.num(features) or 0) // bit) % 2) == 1 end

-- a light's supported_color_modes -> { brightness, temp, color }
function H.light_modes(a)
  local m = { brightness = false, temp = false, color = false }
  local modes = type(a.supported_color_modes) == 'table' and a.supported_color_modes or {}
  for _k, s in ipairs(modes) do
    if s ~= 'onoff' then m.brightness = true end
    if s == 'color_temp' then m.temp = true end
    if s == 'hs' or s == 'xy' or s == 'rgb' or s == 'rgbw' or s == 'rgbww' then m.color = true; m.temp = true end
  end
  if H.num(a.brightness) then m.brightness = true end
  if m.color and not (H.num(a.min_color_temp_kelvin) or H.num(a.min_mireds)) then m.temp = false end
  return m
end

H.WARMTH = { { 'Warm', 2700 }, { 'Soft', 3500 }, { 'Neutral', 4500 }, { 'Daylight', 6000 } }
H.COLOURS = { { 'White', 0, 0 }, { 'Red', 0, 100 }, { 'Orange', 30, 100 }, { 'Yellow', 55, 100 },
              { 'Green', 120, 100 }, { 'Cyan', 180, 100 }, { 'Blue', 230, 100 }, { 'Purple', 280, 100 } }

-- a warmth preset clamped to the light's range
function H.kelvin(a, k)
  local lo, hi = H.num(a.min_color_temp_kelvin) or 2000, H.num(a.max_color_temp_kelvin) or 6500
  return math.floor(math.max(lo, math.min(hi, k)))
end

-- media player features (HA's MediaPlayerEntityFeature)
H.MP = { PAUSE = 1, VOLUME_SET = 4, VOLUME_MUTE = 8, PREVIOUS = 16, NEXT = 32, TURN_ON = 128, TURN_OFF = 256,
         VOLUME_STEP = 1024, SELECT_SOURCE = 2048, STOP = 4096, PLAY = 16384 }
-- cover features (CoverEntityFeature)
H.CV = { OPEN = 1, CLOSE = 2, SET_POSITION = 4, STOP = 8 }

-- the template's lines -> { [id] = row } and the ids in order
function H.parse_rows(body)
  local rows, order = {}, {}
  for line in (tostring(body or '') .. '\n'):gmatch('([^\n]*)\n') do
    local id, state, unit, name, class, extra = line:match('^([^|]*)|([^|]*)|([^|]*)|([^|]*)|([^|]*)|([^|]*)$')
    if id and H.valid_id(id) then
      rows[id] = { id = id, state = state, unit = unit, name = name, class = class, extra = extra }
      order[#order + 1] = id
    end
  end
  return rows, order
end

-- GET /api/states/<id> (decoded JSON) -> a row like the template's
function H.row_from_state(d)
  if type(d) ~= 'table' or not H.valid_id(d.entity_id) then return nil end
  local a = type(d.attributes) == 'table' and d.attributes or {}
  local dom, extra = H.domain(d.entity_id), ''
  if dom == 'climate' then
    local t = H.num(a.temperature) and tostring(a.temperature)
      or (H.num(a.target_temp_low) and (tostring(a.target_temp_low) .. '~' .. tostring(a.target_temp_high))) or ''
    extra = (H.num(a.current_temperature) and tostring(a.current_temperature) or '') .. ';' .. t .. ';' .. (H.str(a.hvac_action) or '')
  elseif dom == 'light' and tonumber(a.brightness) then extra = tostring(math.floor(tonumber(a.brightness) / 2.55 + 0.5))
  elseif dom == 'cover' and tonumber(a.current_position) then extra = tostring(a.current_position)
  elseif dom == 'media_player' and a.media_title then extra = tostring(a.media_title) end
  local function clean(v) return (tostring(v or ''):gsub('[|\n]', ' ')) end
  return { id = d.entity_id, state = clean(d.state), unit = clean(a.unit_of_measurement), name = clean(a.friendly_name or d.entity_id),
           class = clean(a.device_class), extra = clean(extra) }
end

function H.http_error(code)
  if code == 401 or code == 403 then return 'token rejected (' .. code .. ')' end
  if code == 404 then return 'not found (404): is the address right?' end
  return 'HTTP ' .. tostring(code)
end

------------------------------------------------------------------ the cache

function H.cache_text(rows, order, now)
  local out = { 'updated=' .. tostring(now or 0) }
  for _k, id in ipairs(order) do
    local r = rows[id]
    if r then out[#out + 1] = table.concat({ r.id, r.state, r.unit, r.name, r.class, r.extra }, '|') end
  end
  return table.concat(out, '\n')
end
function H.parse_cache(text)
  if not text then return nil end
  local rows, order = H.parse_rows(text)
  return { updated = tonumber(text:match('updated=(%d+)')), rows = rows, order = order }
end

------------------------------------------------------------------ showing a state

local TOGGLE = { light = true, switch = true, input_boolean = true, fan = true, automation = true, siren = true,
                 humidifier = true }

local function cap(s) s = tostring(s or ''):gsub('_', ' '); return (s:gsub('^%l', string.upper)) end

function H.number(s, unit)
  local v = tonumber(s)
  if not v then return nil end
  local t
  if math.abs(v) >= 100 or v == math.floor(v) then t = tostring(math.floor(v + 0.5))
  else t = string.format('%.1f', v):gsub('%.0$', '') end
  if unit and unit ~= '' then t = t .. (unit:sub(1, #'°') == '°' and unit or (' ' .. unit)) end
  return t
end

local BINARY = {
  door = { 'Open', 'Closed' }, window = { 'Open', 'Closed' }, opening = { 'Open', 'Closed' }, garage_door = { 'Open', 'Closed' },
  motion = { 'Motion', 'Clear' }, occupancy = { 'Occupied', 'Clear' }, presence = { 'Home', 'Away' },
  moisture = { 'Wet', 'Dry' }, smoke = { 'Smoke!', 'Clear' }, gas = { 'Gas!', 'Clear' }, problem = { 'Problem', 'OK' },
  safety = { 'Unsafe', 'Safe' }, lock = { 'Unlocked', 'Locked' }, battery = { 'Low', 'OK' }, plug = { 'Plugged in', 'Unplugged' },
  connectivity = { 'Connected', 'Offline' }, running = { 'Running', 'Idle' },
}
local ALERT = { door = true, window = true, opening = true, garage_door = true, moisture = true, smoke = true, gas = true,
                problem = true, safety = true, lock = true }

-- a row -> the value (large), a second line (small, may be ''), and whether the tile is "on"
-- (framed twice: switched on, open, unlocked, home)
function H.shown(row)
  if not row then return '...', '', false end
  local st, dom = row.state or '', H.domain(row.id)
  if st == 'unavailable' or st == 'unknown' or st == '' then return '-', st, false end
  if TOGGLE[dom] then
    local v = st == 'on' and 'On' or st == 'off' and 'Off' or cap(st)
    if dom == 'light' and st == 'on' and row.extra ~= '' then v = v .. ' ' .. row.extra .. '%' end
    return v, '', st == 'on'
  end
  if dom == 'binary_sensor' then
    local b = BINARY[row.class] or { 'On', 'Off' }
    return st == 'on' and b[1] or b[2], '', st == 'on'
  end
  if dom == 'lock' then return cap(st), '', st ~= 'locked' end
  if dom == 'cover' or dom == 'valve' then
    local v = cap(st)
    if st == 'open' and row.extra ~= '' and row.extra ~= '100' then v = v .. ' ' .. row.extra .. '%' end
    return v, '', st ~= 'closed'
  end
  if dom == 'climate' then
    local cur, target, action = H.climate_extra(row.extra)
    local v = H.number(cur, '°') or cap(st)
    if st == 'off' then return v, 'Off', false end
    local busy = action ~= '' and action ~= 'idle' and action ~= 'off'
    if busy then return v, cap(action) .. (target and (' to ' .. target) or ''), true end
    return v, cap(st) .. (target and (' · ' .. target) or ''), action == ''
  end
  if dom == 'media_player' then return cap(st), row.extra or '', st == 'playing' end
  if dom == 'scene' or dom == 'script' then return st == 'on' and 'Running' or 'Run', '', st == 'on' end
  if dom == 'button' or dom == 'input_button' then return 'Press', '', false end
  if dom == 'person' or dom == 'device_tracker' then return cap(st == 'not_home' and 'away' or st), '', st == 'home' end
  if dom == 'sun' then return st == 'above_horizon' and 'Up' or 'Down', '', st == 'above_horizon' end
  local n = H.number(st, row.unit)
  if n then return n, '', false end
  return cap(st), '', false
end

-- a thermostat row's extra "current;target;action" -> current, the target as text ("21°", "18-24°"), action;
-- a cache from version 0.1 or 0.2 holds the current temperature alone
function H.climate_extra(extra)
  local cur, t, action = tostring(extra or ''):match('^([^;]*);([^;]*);(.*)$')
  if not cur then return extra, nil, '' end
  local lo, hi = t:match('^([^~]+)~(.+)$')
  local target
  if lo then target = (H.number(lo, '') or lo) .. '-' .. (H.number(hi, '°') or hi)
  elseif t ~= '' then target = H.number(t, '°') or t end
  return cur, target, action
end

-- what a tap does: domain, service, and a question to ask first (or nil); nil when nothing
function H.action(row)
  if not row then return nil end
  local st, dom = row.state or '', H.domain(row.id)
  if st == 'unavailable' then return nil end
  if TOGGLE[dom] then return dom, 'toggle' end
  if dom == 'scene' or dom == 'script' then return dom, 'turn_on' end
  if dom == 'button' or dom == 'input_button' then return dom, 'press' end
  if dom == 'media_player' then return dom, 'media_play_pause' end
  if dom == 'cover' then return dom, (st == 'closed' or st == 'closing') and 'open_cover' or 'close_cover', true end
  if dom == 'lock' then return dom, st == 'locked' and 'unlock' or 'lock', true end
  return nil
end

-- after a toggle the tile turns at once; the next fetch has the last word
function H.flipped(row)
  local dom = H.domain(row.id)
  if TOGGLE[dom] and (row.state == 'on' or row.state == 'off') then
    local r = {}
    for k, v in pairs(row) do r[k] = v end
    r.state = row.state == 'on' and 'off' or 'on'
    return r
  end
  return nil
end

-- worth a line on the lock screen: open doors and windows, water, smoke, an unlocked lock
function H.alert(row)
  if not row then return false end
  local dom = H.domain(row.id)
  if dom == 'binary_sensor' then return row.state == 'on' and ALERT[row.class] == true end
  if dom == 'lock' then return row.state == 'unlocked' or row.state == 'jammed' or row.state == 'open' end
  if dom == 'cover' then return row.class == 'garage' and row.state == 'open' end
  return false
end

function H.label(tile, row)
  return tile.label or (row and row.name ~= '' and row.name) or tile.id
end

return H
end)()

local D = (function()
-- Drawing pieces shared by the app (src/main.lua) and the lock screen (lockscreen.lua carries its
-- own copy): rounded frames, icons for the kinds of entity, a switch, segmented bars, round and
-- rounded buttons, media glyphs.
--
-- Only g:polyline, g:line, g:circle, g:rect and g:text are used: g:round_rect exists on the
-- device but its arguments were never probed, so a rounded frame is one polyline (17 points;
-- the host takes about 60 a command). Nothing large is filled black (it ghosts on e-ink and the
-- host draws text black on it); "filled" round things are a few circles inside each other.
-- Icons are drawn on a 28-unit grid and scaled to their box.

local D = {}

local function r(v) return math.floor(v + 0.5) end

function D.font(name) return ctx.fonts and ctx.fonts[name] end
function D.width(name, s)
  local ok, w = pcall(function() return D.font(name):measure(s) end)
  return (ok and type(w) == 'number') and w or #s * 11
end
function D.line_h(name)
  local ok, h = pcall(function() return D.font(name).line_height end)
  return (ok and tonumber(h)) or (name == 'large' and 30 or name == 'small' and 20 or 24)
end
-- s cut to fit w pixels (a whole UTF-8 character at a time)
function D.fit(s, name, w)
  s = tostring(s or '')
  if D.width(name, s) <= w then return s end
  while #s > 1 and D.width(name, s .. '~') > w do s = s:gsub('[%z\1-\127\192-\255][\128-\191]*$', '') end
  return s .. '~'
end
function D.text(gg, x, y, s, name) gg:text(r(x), r(y), s, { font = D.font(name or 'medium') }) end
function D.text_c(gg, cx, y, s, name) D.text(gg, cx - D.width(name or 'medium', s) / 2, y, s, name) end
function D.text_r(gg, rx, y, s, name) D.text(gg, rx - D.width(name or 'medium', s), y, s, name) end

function D.circle(gg, x, y, rad) pcall(function() gg:circle(r(x), r(y), r(rad)) end) end
-- a solid-looking small disc
function D.disc(gg, x, y, rad)
  local k = rad
  while k >= 1 do D.circle(gg, x, y, k); k = k - 1 end
end

-- a rounded frame; thick draws it again inside itself
function D.rrect(gg, x, y, w, h, rad, thick)
  for k = 0, (thick or 1) - 1 do
    local xx, yy, ww, hh = x + k, y + k, w - 2 * k, h - 2 * k
    local rr = math.max(2, math.min(rad - k, ww // 2, hh // 2))
    local pts = {}
    local C = { { xx + ww - rr, yy + rr, -90 }, { xx + ww - rr, yy + hh - rr, 0 }, { xx + rr, yy + hh - rr, 90 }, { xx + rr, yy + rr, 180 } }
    for _c, c in ipairs(C) do
      for s = 0, 3 do
        local a = math.rad(c[3] + s * 30)
        pts[#pts + 1] = r(c[1] + rr * math.cos(a)); pts[#pts + 1] = r(c[2] + rr * math.sin(a))
      end
    end
    pts[#pts + 1] = pts[1]; pts[#pts + 1] = pts[2]
    gg:polyline(pts)
  end
end

------------------------------------------------------------------ icons

-- which icon a row gets
function D.kind(row)
  if not row then return 'dot' end
  local dom = (tostring(row.id):match('^([^.]+)%.')) or ''
  local c = row.class or ''
  if dom == 'light' then return 'bulb' end
  if dom == 'switch' or dom == 'input_boolean' or dom == 'automation' or dom == 'siren' then return 'power' end
  if dom == 'fan' then return 'fan' end
  if dom == 'climate' or dom == 'water_heater' then return 'thermo' end
  if dom == 'media_player' then return 'speaker' end
  if dom == 'scene' then return 'star' end
  if dom == 'script' then return 'play' end
  if dom == 'button' or dom == 'input_button' then return 'button' end
  if dom == 'person' or dom == 'device_tracker' then return 'person' end
  if dom == 'sun' or dom == 'weather' then return 'sun' end
  if dom == 'lock' then return row.state == 'locked' and 'lock' or 'unlock' end
  if dom == 'cover' then return (c == 'garage' or c == 'gate') and 'garage' or 'blind' end
  if dom == 'binary_sensor' then
    if c == 'door' or c == 'garage_door' or c == 'opening' then return row.state == 'on' and 'door_open' or 'door' end
    if c == 'window' then return 'window' end
    if c == 'motion' or c == 'occupancy' or c == 'presence' then return 'motion' end
    if c == 'moisture' then return 'drop' end
    if c == 'smoke' or c == 'gas' or c == 'problem' or c == 'safety' then return 'alert' end
    if c == 'lock' then return row.state == 'on' and 'unlock' or 'lock' end
    return 'dot'
  end
  if dom == 'sensor' or dom == 'number' or dom == 'input_number' then
    if c == 'temperature' then return 'thermo' end
    if c == 'humidity' or c == 'moisture' then return 'drop' end
    if c == 'power' or c == 'energy' or c == 'current' or c == 'voltage' then return 'bolt' end
    if c == 'battery' then return 'battery' end
    if c == 'illuminance' then return 'sun' end
    return 'gauge'
  end
  return 'dot'
end

-- points on a circle of the 28-grid: centre (cx, cy), radius rad, from a0 to a1 degrees by step
local function arc(cx, cy, rad, a0, a1, step)
  local t, a = {}, a0
  while (step > 0 and a <= a1) or (step < 0 and a >= a1) do
    t[#t + 1] = cx + rad * math.cos(math.rad(a)); t[#t + 1] = cy + rad * math.sin(math.rad(a))
    a = a + step
  end
  return t
end

local SHAPES = {
  bulb = function(P, C, on)
    C(14, 11, 8); P({ 10, 18, 11, 22, 17, 22, 18, 18 }); P({ 11, 25, 17, 25 })
    if on then P({ 1, 11, 3, 11 }); P({ 25, 11, 27, 11 }); P({ 4, 1, 6, 3 }); P({ 24, 1, 22, 3 }) end
  end,
  power = function(P) P(arc(14, 15, 10, -60, 240, 30)); P({ 14, 1, 14, 13 }) end,
  fan = function(P, C)
    C(14, 14, 3)
    P({ 14, 11, 9, 3, 16, 1, 16, 11 }); P({ 17, 15, 26, 16, 24, 22, 16, 17 }); P({ 12, 16, 7, 25, 2, 20, 11, 14 })
  end,
  thermo = function(P, C, _on, Dk)
    P({ 11, 19, 11, 4, 12, 2, 16, 2, 17, 4, 17, 19 }); C(14, 22, 5); Dk(14, 22, 3); P({ 14, 8, 14, 20 })
  end,
  drop = function(P) P({ 14, 2, 7, 14, 7, 18, 10, 23, 14, 25, 18, 23, 21, 18, 21, 14, 14, 2 }) end,
  bolt = function(P) P({ 17, 1, 6, 16, 13, 16, 11, 27, 22, 11, 15, 11, 17, 1 }) end,
  battery = function(P, _C, _on, _Dk, F) P({ 2, 8, 23, 8, 23, 20, 2, 20, 2, 8 }); P({ 24, 11, 26, 11, 26, 17, 24, 17 }); F(5, 11, 10, 7) end,
  gauge = function(P) P(arc(14, 19, 12, 180, 360, 30)); P({ 2, 19, 26, 19 }); P({ 14, 19, 20, 10 }) end,
  door = function(P, C) P({ 6, 26, 6, 2, 22, 2, 22, 26 }); P({ 2, 26, 26, 26 }); C(18, 15, 1) end,
  door_open = function(P) P({ 6, 26, 6, 2, 22, 2, 22, 26 }); P({ 2, 26, 26, 26 }); P({ 6, 2, 15, 6, 15, 24, 6, 26 }) end,
  window = function(P) P({ 4, 3, 24, 3, 24, 25, 4, 25, 4, 3 }); P({ 14, 3, 14, 25 }); P({ 4, 14, 24, 14 }) end,
  motion = function(P, C)
    C(17, 4, 3); P({ 16, 8, 13, 16, 17, 19, 17, 27 }); P({ 14, 11, 8, 14 }); P({ 15, 10, 21, 13 }); P({ 13, 16, 8, 26 })
  end,
  lock = function(P, C) P({ 5, 13, 23, 13, 23, 26, 5, 26, 5, 13 }); P({ 9, 13, 9, 7, 11, 3, 17, 3, 19, 7, 19, 13 }); C(14, 19, 2) end,
  unlock = function(P, C) P({ 5, 13, 23, 13, 23, 26, 5, 26, 5, 13 }); P({ 9, 13, 9, 5, 11, 1, 17, 1, 19, 5, 19, 8 }); C(14, 19, 2) end,
  speaker = function(P) P({ 3, 10, 8, 10, 15, 4, 15, 24, 8, 18, 3, 18, 3, 10 }); P({ 19, 10, 21, 14, 19, 18 }); P({ 22, 6, 26, 14, 22, 22 }) end,
  star = function(P)
    local t = {}
    for k = 0, 10 do
      local rad = (k % 2 == 0) and 13 or 5.5
      local a = math.rad(-90 + k * 36)
      t[#t + 1] = 14 + rad * math.cos(a); t[#t + 1] = 15 + rad * math.sin(a)
    end
    P(t)
  end,
  play = function(P) P({ 7, 3, 24, 14, 7, 25, 7, 3 }) end,
  button = function(_P, C, _on, Dk) C(14, 14, 12); Dk(14, 14, 5) end,
  person = function(P, C) C(14, 8, 6); P({ 3, 27, 4, 22, 8, 17, 20, 17, 24, 22, 25, 27 }) end,
  sun = function(P, C)
    C(14, 14, 6)
    for k = 0, 7 do
      local a = math.rad(k * 45)
      P({ 14 + 9 * math.cos(a), 14 + 9 * math.sin(a), 14 + 13 * math.cos(a), 14 + 13 * math.sin(a) })
    end
  end,
  garage = function(P) P({ 1, 12, 14, 3, 27, 12 }); P({ 4, 10, 4, 26, 24, 26, 24, 10 }); P({ 8, 26, 8, 14, 20, 14, 20, 26 }); P({ 8, 18, 20, 18 }); P({ 8, 22, 20, 22 }) end,
  blind = function(P, C) P({ 3, 3, 25, 3 }); P({ 5, 8, 23, 8 }); P({ 5, 13, 23, 13 }); P({ 5, 18, 23, 18 }); P({ 14, 18, 14, 24 }); C(14, 25, 2) end,
  alert = function(P, C) P({ 14, 2, 27, 25, 1, 25, 14, 2 }); P({ 14, 9, 14, 17 }); C(14, 21, 1) end,
  dot = function(_P, C) C(14, 14, 7); C(14, 14, 2) end,
}

-- an icon of kind in a box of size s at (x, y)
function D.icon(gg, kind, x, y, s, on)
  local f = s / 28
  local function P(t)
    local o = {}
    for i, v in ipairs(t) do o[i] = r((i % 2 == 1) and (x + v * f) or (y + v * f)) end
    gg:polyline(o)
  end
  local function C(cx, cy, rad) D.circle(gg, x + cx * f, y + cy * f, math.max(1, rad * f)) end
  local function Dk(cx, cy, rad) D.disc(gg, x + cx * f, y + cy * f, math.max(1, rad * f)) end
  local function F(fx, fy, fw, fh) gg:rect(r(x + fx * f), r(y + fy * f), math.max(1, r(fw * f)), math.max(1, r(fh * f)), { fill = true }) end
  local sh = SHAPES[kind] or SHAPES.dot
  sh(P, C, on, Dk, F)
end

------------------------------------------------------------------ controls

-- an on/off switch: a pill with its knob right (on, filled) or left (off, hollow)
function D.switch(gg, x, y, w, h, on)
  D.rrect(gg, x, y, w, h, h // 2, on and 2 or 1)
  local kr = h // 2 - 5
  if on then D.disc(gg, x + w - h // 2, y + h // 2, kr) else D.circle(gg, x + h // 2, y + h // 2, kr) end
end

-- a thin bar filled to frac (0..1)
function D.bar(gg, x, y, w, h, frac)
  D.rrect(gg, x, y, w, h, h // 2, 1)
  local fw = math.floor((w - 4) * math.max(0, math.min(1, frac or 0)))
  if fw > 0 then gg:rect(x + 2, y + 2, fw, h - 4, { fill = true }) end
end

-- n rounded segments across w, the first filled ones solid; returns each segment's x and width
function D.segments(gg, x, y, w, h, n, filled, gap)
  gap = gap or 6
  local sw = (w - (n - 1) * gap) // n
  local xs = {}
  for k = 1, n do
    local sx = x + (k - 1) * (sw + gap)
    xs[k] = sx
    D.rrect(gg, sx, y, sw, h, 7, 1)
    if k <= (filled or 0) then gg:rect(sx + 6, y + 6, sw - 12, h - 12, { fill = true }) end
  end
  return xs, sw
end

-- a rounded button with a centred label; opts: font, sel (drawn thick), off (thin, label in brackets)
function D.button(gg, x, y, w, h, label, opts)
  opts = opts or {}
  local fname = opts.font or 'medium'
  D.rrect(gg, x, y, w, h, opts.radius or 12, opts.sel and 3 or (opts.off and 1 or 2))
  if label and label ~= '' then
    local s = D.fit(opts.off and ('(' .. label .. ')') or label, fname, w - 12)
    D.text(gg, x + (w - D.width(fname, s)) / 2, y + (h - D.line_h(fname)) / 2, s, fname)
  end
end

-- media and step glyphs centred on (cx, cy), about s tall
function D.glyph(gg, kind, cx, cy, s)
  local h = s / 2
  local function P(t) local o = {} for i, v in ipairs(t) do o[i] = r(v) end gg:polyline(o) end
  local function F(x, y, w, hh) gg:rect(r(x), r(y), math.max(1, r(w)), math.max(1, r(hh)), { fill = true }) end
  if kind == 'play' then
    P({ cx - h * 0.6, cy - h, cx + h, cy, cx - h * 0.6, cy + h, cx - h * 0.6, cy - h })
    P({ cx - h * 0.4, cy - h * 0.6, cx + h * 0.6, cy, cx - h * 0.4, cy + h * 0.6, cx - h * 0.4, cy - h * 0.6 })
  elseif kind == 'pause' then
    F(cx - h * 0.7, cy - h, h * 0.45, 2 * h); F(cx + h * 0.25, cy - h, h * 0.45, 2 * h)
  elseif kind == 'next' or kind == 'prev' then
    local d = kind == 'next' and 1 or -1
    for k = 0, 1 do
      local o = (k == 0 and -h * 0.9 or 0) * d
      P({ cx + o, cy - h * 0.8, cx + o + h * 0.9 * d, cy, cx + o, cy + h * 0.8, cx + o, cy - h * 0.8 })
    end
    F(kind == 'next' and (cx + h * 0.9) or (cx - h * 0.9 - 3), cy - h * 0.8, 3, h * 1.6)
  elseif kind == 'plus' or kind == 'minus' then
    F(cx - h * 0.7, cy - 2, h * 1.4, 4)
    if kind == 'plus' then F(cx - 2, cy - h * 0.7, 4, h * 1.4) end
  elseif kind == 'back' then
    for k = 0, 2 do P({ cx + h * 0.4 + k, cy - h * 0.8, cx - h * 0.4 + k, cy, cx + h * 0.4 + k, cy + h * 0.8 }) end
  elseif kind == 'chevron' then
    P({ cx - h * 0.3, cy - h * 0.6, cx + h * 0.3, cy, cx - h * 0.3, cy + h * 0.6 })
  elseif kind == 'up' or kind == 'down' then
    local d = kind == 'up' and -1 or 1
    P({ cx - h * 0.8, cy - d * h * 0.3, cx, cy + d * h * 0.5, cx + h * 0.8, cy - d * h * 0.3 })
  elseif kind == 'stop' then
    P({ cx - h * 0.6, cy - h * 0.6, cx + h * 0.6, cy - h * 0.6, cx + h * 0.6, cy + h * 0.6, cx - h * 0.6, cy + h * 0.6, cx - h * 0.6, cy - h * 0.6 })
  end
end

-- a round button with a glyph (or the glyph in brackets of a thin ring when off)
function D.round(gg, cx, cy, rad, glyph, opts)
  opts = opts or {}
  D.circle(gg, cx, cy, rad)
  if not opts.off then D.circle(gg, cx, cy, rad - 1); if opts.sel then D.circle(gg, cx, cy, rad - 2) end end
  if not opts.off then D.glyph(gg, glyph, cx, cy, rad * 0.8) end
end

------------------------------------------------------------------ the date

local MONTHS = { 'January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October',
                 'November', 'December' }
local WEEKDAYS = { 'Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday' }

-- ctx.clock:now() -> "Tuesday, 28 October", from the local time of day and the epoch
function D.date(t)
  if type(t) ~= 'table' or not tonumber(t.epoch_sec) or not tonumber(t.hour) then return '' end
  local ep = math.floor(tonumber(t.epoch_sec))
  local local_sod = tonumber(t.hour) * 3600 + (tonumber(t.minute) or 0) * 60 + (tonumber(t.second) or 0)
  local off = local_sod - ep % 86400
  if off > 14 * 3600 then off = off - 86400 elseif off < -12 * 3600 then off = off + 86400 end
  local days = (ep + off) // 86400
  -- civil date from days since 1970-01-01 (H. Hinnant's algorithm)
  local z = days + 719468
  local era = z // 146097
  local doe = z - era * 146097
  local yoe = (doe - doe // 1460 + doe // 36524 - doe // 146096) // 365
  local doy = doe - (365 * yoe + yoe // 4 - yoe // 100)
  local mp = (5 * doy + 2) // 153
  local d = doy - (153 * mp + 2) // 5 + 1
  local m = mp < 10 and mp + 3 or mp - 9
  return WEEKDAYS[(days + 4) % 7 + 1] .. ', ' .. d .. ' ' .. MONTHS[m]
end
function D.clock(t)
  if type(t) ~= 'table' or not tonumber(t.hour) then return '' end
  return string.format('%02d:%02d', tonumber(t.hour), tonumber(t.minute) or 0)
end

return D
end)()

-- Lock-screen entry for Home Assistant (API 2.9; bundle.py puts src/ha.lua in front as `H` and
-- src/draw.lua as `D`). Shows the time and date, the pinned tiles (or the first eight) from
-- states.txt, and a box listing every open door or window, water, smoke or unlocked lock among the
-- tiles. Redrawn every minute for the clock; when the states are over ten minutes old it asks Home
-- Assistant again, if the reader lets a locked app use the network (if not, it says how old they are).

local W, HH = 480, 800
local STALE_S = 10 * 60
local asked_at = nil

local function read(name)
  local ok, s = pcall(function() return ctx.storage:read(name) end)
  return (ok and type(s) == 'string') and s or nil
end
local function now()
  local ok, t = pcall(function() return ctx.clock:now() end)
  return (ok and type(t) == 'table') and t or {}
end
local function now_sec() local t = now(); return tonumber(t.epoch_sec) and math.floor(tonumber(t.epoch_sec)) or 0 end

local function try_refresh(cfg, tiles)
  if cfg.url == '' or cfg.token == '' or #tiles == 0 or (asked_at and now_sec() - asked_at < STALE_S) then return end
  asked_at = now_sec()
  local ids = {}
  for k, t in ipairs(tiles) do ids[k] = t.id end
  pcall(function()
    ctx.net:request(H.states_request(cfg, ids), function(c, resp)
      pcall(function()
        if type(resp) ~= 'table' or type(resp.body) ~= 'string' or (tonumber(resp.status) or 200) >= 400 then return end
        local rows, order = H.parse_rows(resp.body)
        if #order == 0 then return end
        ctx.storage:write('states.txt', H.cache_text(rows, ids, now_sec()))
        pcall(function() ctx.invalidate() end)
      end)
    end)
  end)
end

function on_draw(c, gg)
  if not gg then return end
  local ok, err = pcall(function()
    gg:clear(0)
    local cfg = H.parse_cfg(read('ha.txt'))
    local tiles = H.parse_tiles(read('tiles.txt'))
    local cache = H.parse_cache(read('states.txt'))
    if #tiles == 0 or not cache then
      D.icon(gg, 'bulb', W / 2 - 40, 300, 80, false)
      D.text_c(gg, W / 2, 410, 'Home Assistant: open the app to add tiles.', 'medium')
      return
    end
    local age = now_sec() - (cache.updated or 0)
    if age > STALE_S then try_refresh(cfg, tiles) end

    local t = now()
    D.text(gg, 24, 20, D.fit(cfg.title, 'large', W - 160), 'large')
    D.text(gg, 24, 58, D.date(t), 'small')
    D.text_r(gg, W - 24, 20, D.clock(t), 'large')
    gg:line(24, 92, W - 24, 92)

    local tw, th = 210, 118
    for k, tl in ipairs(H.lock_tiles(tiles)) do
      local row = cache.rows[tl.id]
      local v, sub, on = H.shown(row)
      local x, y = 24 + ((k - 1) % 2) * (tw + 12), 108 + ((k - 1) // 2) * (th + 12)
      D.rrect(gg, x, y, tw, th, 18, on and 3 or 1)
      D.icon(gg, D.kind(row), x + 14, y + 14, 30, on)
      D.text(gg, x + 54, y + 20, D.fit(H.label(tl, row), 'small', tw - 66), 'small')
      D.text(gg, x + 14, y + 52, D.fit(v, 'large', tw - 28), 'large')
      if H.domain(tl.id) == 'light' and on and tonumber(row.extra) then
        D.bar(gg, x + 14, y + th - 18, tw - 28, 8, tonumber(row.extra) / 100)
      elseif sub ~= '' then
        D.text(gg, x + 14, y + th - 28, D.fit(sub, 'small', tw - 28), 'small')
      end
    end

    local open = {}
    for _k, tl in ipairs(tiles) do
      local row = cache.rows[tl.id]
      if H.alert(row) then open[#open + 1] = H.label(tl, row) .. ' (' .. (H.shown(row)) .. ')' end
    end
    local y = 640
    if #open > 0 then
      local lines, line = {}, ''
      for _k, s in ipairs(open) do
        local cand = line == '' and s or (line .. ', ' .. s)
        if line ~= '' and D.width('medium', cand) > W - 150 then lines[#lines + 1] = line; line = s else line = cand end
      end
      lines[#lines + 1] = line
      local n = math.min(3, #lines)
      D.rrect(gg, 24, y - 14, W - 48, n * 30 + 26, 18, 2)
      D.icon(gg, 'alert', 40, y - 2 + (n - 1) * 15, 30)
      for k = 1, n do D.text(gg, 86, y + (k - 1) * 30, D.fit(lines[k], 'medium', W - 130), 'medium') end
    else
      D.icon(gg, 'door', 24, y, 26, false)
      D.text(gg, 62, y + 2, 'All doors and windows closed.', 'small')
    end
    local mins = age // 60
    D.text(gg, 24, HH - 40, mins < 90 and ('updated ' .. mins .. ' min ago') or ('updated ' .. (mins // 60) .. ' h ago'), 'small')
  end)
  if not ok then pcall(function() gg:text(10, 760, 'lock error: ' .. tostring(err):sub(1, 40)) end) end
end

function on_load() end
function on_tick() end
function on_input() return false end
